<?php
// Local MySQL only. An empty disposable database is removed on exit.
require __DIR__.'/../config/database.php';
require __DIR__.'/../includes/asset_link_service.php';
if(!$pdo)throw new RuntimeException('Local MySQL required');
function link_check($condition,string $message): void {if(!$condition)throw new RuntimeException($message);}
require __DIR__.'/mysql_fixture.php';sena_test_database($pdo,$host);
$pdo->exec("INSERT INTO equipment_registry(id,equipment_name,equipment_code,location,image_url) VALUES(1,'Old A','A-1','Library','uploads/existing.jpg'),(2,'Duplicate one','D-1','Room 1',NULL),(3,'Duplicate two','D-1','Room 2',NULL)");
$annual=$pdo->prepare('INSERT INTO inspection_items(item_number,item_name,asset_code,fiscal_year,status_usable,status_damaged,remarks) VALUES(?,?,?,2568,1,1,?)');
foreach([[1,'Annual A'," A-1 \n"],[2,'Unmatched','B-1'],[3,'No code',''],[4,'Ambiguous duplicate','D-1'],[5,'Repeated annual code','A-1']] as $r)$annual->execute([...$r,'keep annual remarks']);
$observations=$pdo->query('SELECT id,status_usable,status_damaged,remarks FROM inspection_items ORDER BY id')->fetchAll();
$result=sena_link_inspection_year($pdo,2568,false);
link_check($result===['linked'=>5,'created'=>4],'Match unique codes; never merge missing, repeated or ambiguous identities');
$rows=$pdo->query('SELECT * FROM inspection_items ORDER BY item_number')->fetchAll();
link_check(count(array_unique(array_column($rows,'registry_id')))===5,'Each annual row needs its own registry identity');
link_check((int)$rows[0]['registry_id']===1,'Unique legacy record and photo identity retained');
link_check($rows[0]['image_url']==='uploads/existing.jpg','Existing photo retained');
link_check($pdo->query('SELECT id,status_usable,status_damaged,remarks FROM inspection_items ORDER BY id')->fetchAll()===$observations,'Historical results and remarks retained');
link_check((int)$pdo->query('SELECT COUNT(*) FROM equipment_registry WHERE id IN (1,2,3)')->fetchColumn()===3,'Old registry records retained');
link_check((int)$pdo->query('SELECT COUNT(*) FROM '.sena_registry_source_sql(2568))->fetchColumn()===5,'Registry view matches annual count');
link_check(sena_link_inspection_year($pdo,2568,false)===['linked'=>0,'created'=>0],'Repeat linking must be idempotent');
$pdo->beginTransaction();
$pdo->exec("INSERT INTO equipment_registry(equipment_name,equipment_code,category,location,image_url) VALUES('Added in registry','NEW-1','Test','Office','uploads/new.jpg')");
$newId=(int)$pdo->lastInsertId();$inspectionId=sena_attach_registry_to_year($pdo,$newId,2568);
$pdo->commit();
link_check(sena_attach_registry_to_year($pdo,$newId,2568)===$inspectionId,'Attach twice must not duplicate');
link_check((int)$pdo->query('SELECT COUNT(*) FROM '.sena_registry_source_sql(2568))->fetchColumn()===6,'Adding in registry adds annual row');
$pdo->exec("UPDATE equipment_registry SET equipment_name='Renamed',equipment_code='RENAMED-1' WHERE id=$newId");
sena_sync_registry_details($pdo,$newId);
link_check($pdo->query("SELECT item_name FROM inspection_items WHERE id=$inspectionId")->fetchColumn()==='Renamed','Registry edits reach annual');
$pdo->exec("UPDATE inspection_items SET item_name='Edited in annual',location='New office' WHERE id=$inspectionId");
sena_sync_inspection_details($pdo,$inspectionId);
link_check($pdo->query("SELECT equipment_name FROM equipment_registry WHERE id=$newId")->fetchColumn()==='Edited in annual','Annual edits reach registry');
$nextYearId=sena_attach_registry_to_year($pdo,$newId,2570);
sena_set_asset_photo($pdo,$newId,'uploads/shared.jpg');
link_check((int)$pdo->query("SELECT COUNT(*) FROM inspection_items WHERE registry_id=$newId AND image_url='uploads/shared.jpg'")->fetchColumn()===2,'Photo propagates to linked years');
link_check($pdo->query('SELECT image_url FROM equipment_registry WHERE id=1')->fetchColumn()==='uploads/existing.jpg','Unrelated same-code objects retain their photo');
sena_registry_status_to_year($pdo,$newId,2568,'damaged');
link_check((int)$pdo->query("SELECT status_damaged FROM inspection_items WHERE id=$inspectionId")->fetchColumn()===1,'Current year status follows explicit master edit');
link_check((int)$pdo->query("SELECT status_damaged FROM inspection_items WHERE id=$nextYearId")->fetchColumn()===0,'Other-year status stays independent');
link_check($pdo->query('SELECT status FROM '.sena_registry_source_sql(2568)." WHERE id=$newId")->fetchColumn()==='damaged','Registry uses selected-year status');
link_check($pdo->query('SELECT status FROM '.sena_registry_source_sql(2570)." WHERE id=$newId")->fetchColumn()==='unverified','Registry does not inherit a different year status');
$pdo->exec("INSERT INTO inspection_items(item_number,item_name,asset_code,fiscal_year) VALUES(7,'Added in annual','NEW-ANNUAL',2568)");
$addedId=(int)$pdo->lastInsertId();sena_link_inspection_year($pdo,2568,false);
link_check((int)$pdo->query("SELECT registry_id FROM inspection_items WHERE id=$addedId")->fetchColumn()>0,'Adding in annual creates registry identity');
link_check((int)$pdo->query('SELECT COUNT(*) FROM '.sena_registry_source_sql(2568))->fetchColumn()===7,'Both lists remain equal after adds from either side');
require __DIR__.'/../includes/import_service.php';
$preserved=$pdo->query('SELECT * FROM inspection_items WHERE id=1')->fetch(PDO::FETCH_ASSOC);
$import=['item_number'=>1,'item_name'=>'Annual imported again','asset_code'=>'A-1','fiscal_year'=>2568,'status_usable'=>1,'status_damaged'=>1,'source_key'=>'inspection:fixture:2568:1'];
sena_import($pdo,'inspection',[$import],true);
$restored=$pdo->query('SELECT * FROM inspection_items WHERE id=1')->fetch(PDO::FETCH_ASSOC);
link_check($restored['registry_id']===$preserved['registry_id']&&$restored['image_url']===$preserved['image_url'],'Annual reimport keeps IDs, links and photos');
link_check((int)$pdo->query('SELECT COUNT(*) FROM '.sena_registry_source_sql(2568))->fetchColumn()===1,'Annual reimport updates scoped registry view');
echo "Stable links, duplicates, missing codes, both add/edit directions, shared photos, independent annual results and idempotency passed\n";
